update public.heros set
  frise_chronologique_en = $t$[{"date": "c. 1880-1883", "evenement": "born under the name Ntsama in Mvolyé (present-day Yaoundé), eleventh child of Essomba Atangana, a Mvog Atemenge notable among the Ewondo (sources vary between 1876 and 1885); lost his father at around the age of six"}, {"date": "1896-1900", "evenement": "educated at the Pallottine mission in Kribi, Catholic baptism (the first Ewondo to be baptised), schooling interrupted by the Bulu revolt of 1899; became an interpreter for Bulu forced labourers in Victoria in 1900, then a clerk in Buea"}, {"date": "1902-1910", "evenement": "official German representative to the Ewondo in charge of the census and taxes (1902), then right-hand man of commander Hans Dominik on administrative tours (1904-1910); in 1907, denounced to the Germans a plot hatched against him by the Mvog Ada sub-lineage, which led to the execution of six conspirators"}, {"date": "1911-1913", "evenement": "appointed president of the court and paramount chief of the Ewondo and the Bane by the Germans (1911), an unprecedented title that worried, among others, the Bulu chief Martin Paul Samba; stay in Germany to teach Ewondo at the University of Hamburg and write the Jaunde-Texte (1911-1912); received by Kaiser Wilhelm II and Pope Pius X (1913)"}, {"date": "1914-1920", "evenement": "approached by Rudolf Duala Manga Bell's envoys to support a pan-African uprising, he kept silent, neither joining them nor denouncing them himself (it was Sultan Njoya of the Bamum who alerted the Germans); fled with the routed German troops to Spanish Guinea (1916), exiled in Spain, received by King Alfonso XIII (1919)"}, {"date": "1920-1943", "evenement": "returned to Cameroon under French mandate (November 1920), a probation period in Dschang, reinstated as paramount chief (1921-1922); accumulated wealth and power under the French administration, challenged by the Bane in 1924, invented a royal ancestry in 1929, opposed the spread of schooling; died on 1 September 1943 in Mvolyé"}]$t$::jsonb,
  citations_en = $t$[{"texte": "To dare approach the Germans, one must give up the traits they dislike, become their friend, and then be valued by them.", "source": "Reported by historian Frederick Quinn (“Charles Atangana of Yaounde”, The Journal of African History, 1980).", "statut_attestation": "attestee"}, {"texte": "We keep working and it is Atangana who receives the money. For everything we sent to the Europeans, chickens and eggs, through Atangana, we received nothing.", "source": "Complaint lodged by Bane chiefs in 1924, French colonial archives, quoted by Frederick Quinn.", "statut_attestation": "attestee"}]$t$::jsonb,
  legendes_associees_en = $t$[{"titre": "Precisely counted personal fortunes", "statut": "legende", "description": "Some popular accounts mention extremely precise personal fortunes (exact plantation areas, number of head of cattle) that come from oral testimonies reported long after the events, judged “probably exaggerated” by the historiography itself: symbolic orders of magnitude rather than exact accounting data."}, {"titre": "The invented Ewondo royal ancestry (1929)", "statut": "legende", "description": "Atangana's own claim, in 1929, to an Ewondo royal ancestry going back to fictitious origins should be treated as a self-legitimising story he built, not as an established genealogical fact: the sources agree on the modest nature of his actual birth."}]$t$::jsonb
where slug = $t$charles-atangana$t$;

update public.heros set
  frise_chronologique_en = $t$[{"date": "1924", "evenement": "born in a village in Bamileke country, western Cameroon (sources differ on the exact name of the village and on details of his family)"}, {"date": "November 1943", "evenement": "obtained the native monitor diploma at the École primaire supérieure in Yaoundé, became a schoolteacher"}, {"date": "1948", "evenement": "joined the UPC; elected vice-president of the party in 1952"}, {"date": "13 July 1955", "evenement": "the UPC was banned by the French administration; the party went underground and the armed struggle began"}, {"date": "1958-1964", "evenement": "assassination of Ruben Um Nyobè (13 September 1958), poisoning of Félix-Roland Moumié (died 4 November 1960), death in exile of Abel Kingué (16 June 1964): Ouandié became, in that order, a leader and then the last surviving historic head of the UPC, leading the armed struggle after his clandestine return to Cameroon in July 1961"}, {"date": "19 August 1970", "evenement": "captured near Mbanga after a decade in the maquis, following the failed mediation of Bishop Albert Ndongmo and the betrayal of a catechist"}, {"date": "15 January 1971", "evenement": "publicly executed by a squad of Cameroonian soldiers commanded by a French officer, on the market square in Bafoussam, in front of about 40,000 people, alongside Gabriel Tabeu and Raphaël Fotsing"}, {"date": "16 December 1991", "evenement": "rehabilitated and declared a national hero by law no. 91/022 (after the vote of the Cameroonian National Assembly on 27 June 1991)"}]$t$::jsonb,
