update public.heros set
  frise_chronologique_en = $t$[{"date": "c. 1874-1875", "evenement": "born under the name Mebenga m'Ebono near Ebolowa, Bulu people (sources vary between 1874 and 1875; lost both his father and mother very early)"}, {"date": "1891", "evenement": "sent to Germany for military training on the initiative of the German explorer Kurt von Morgan; baptised Martin-Paul Samba"}, {"date": "1894-1902", "evenement": "officer in the service of the German colonial administration, took part in Hans Dominik's “pacification” expeditions against other Cameroonian communities, before resigning in 1902 to settle as a businessman in Ebolowa"}, {"date": "1910-1912", "evenement": "became a chief in the Bulu hierarchy (1910); the Germans' elevation of chief Charles Atangana as paramount chief of the Ewondo (1911) fuelled his concerns; with the Duala chief Rudolf Duala Manga Bell, he began secretly preparing an uprising and seeking French and British weapons"}, {"date": "1 August 1914", "evenement": "arrested after the interception of a letter addressed to the French forces in Brazzaville, charged with high treason"}, {"date": "8 August 1914", "evenement": "executed by a German firing squad in Ebolowa (the same day, in Douala, in a separate case, the Germans hanged Rudolf Duala Manga Bell and his adviser Ngosso Din)"}]$t$::jsonb,
  citations_en = $t$[]$t$::jsonb,
  legendes_associees_en = $t$[{"titre": "The white handkerchief and the words of defiance before the firing squad", "statut": "legende", "description": "The gesture of the white handkerchief waved at the firing squad, the refusal of the blindfold, and the sentence “I am not afraid of death, kill me but you will never have Cameroon” are reported by many Cameroonian sources as a story handed down in the popular memory of Ebolowa, never backed by a dated and signed testimony from the time of the events."}, {"titre": "“Martin Paul Samba, beyond the legend”", "statut": "legende", "description": "A Cameroonian documentary devoted to his life bears this very title, a sign that the building of his collective memory in Cameroon readily goes beyond the strictly documented facts."}]$t$::jsonb
