  frise_chronologique_en = $t$[{"date": "c. 1583", "evenement": "born in Kabasa, daughter of King Kiluanji kia Samba and Kangela"}, {"date": "1621-1622", "evenement": "embassy to Luanda to negotiate peace on behalf of her brother Ngola Mbandi; Catholic baptism under the name Ana de Sousa (1622)"}, {"date": "1624", "evenement": "death of Mbandi, Njinga's accession to the throne of Ndongo"}, {"date": "15 March 1626", "evenement": "Portugal declared war on Njinga; successive defeats, expelled from her kingdom around 1628-1629"}, {"date": "1631-1635", "evenement": "alliance with and integration into the Imbangala, conquest of the kingdom of Matamba, of which she became queen"}, {"date": "1641-1648", "evenement": "military alliance with the United Provinces (the Dutch) against Portugal; partial reconquest of Ndongo; victories at Ngoleme (1644) and Kombi (1647); Dutch withdrawal after the Portuguese retook Luanda (1648)"}, {"date": "1656", "evenement": "signed a peace treaty with Portugal after nearly 25 years of war; she kept the sovereignty of Matamba"}, {"date": "17 December 1663", "evenement": "died in Matamba; succeeded by her sister Kambu (Barbara)"}]$t$::jsonb,
