update public.heros set
  frise_chronologique_en = $t$[{"date": "c. 1860", "evenement": "birth of Njoya, son of King Nsangu (date of birth uncertain depending on the sources, sometimes estimated later; his father died in battle against the Nso during his childhood, with a regency held by his mother, Queen Njapdunke)"}, {"date": "1892-1895", "evenement": "civil war in the Bamum kingdom, won by Njoya with the support of Sultan Oumarou of Banyo, which allowed him to establish his personal authority"}, {"date": "1896-1918", "evenement": "design and gradual refinement of the Bamum script through seven successive versions (from nearly 500 pictograms to a final syllabary of about 80 signs, known as “A ka u ku”); the first schools opened at the palace from 1898 to teach it"}, {"date": "1908", "evenement": "gave his royal throne Mandu Yenu to Emperor Wilhelm II of Germany after a joint military campaign against the kingdom of the Nso (the throne is now held at the Ethnological Museum in Berlin); received a Prussian military uniform in return"}, {"date": "1913-1920", "evenement": "rebuilding of the Foumban palace after a fire (completed in 1917); construction of a printing press for the Bamum script, completed in 1920 but destroyed before use under pressure from the French colonial administration"}, {"date": "1931", "evenement": "deposed and exiled to Yaoundé by the French administration; died in exile on 30 May 1933"}]$t$::jsonb,
  citations_en = $t$[{"texte": "If you draw many different things and give them a name, I will make a book that speaks without being heard.", "source": "Words attributed to Njoya at the launch of the writing project, relayed by historical studies on the origins of the Bamum script; linked to the story of the founding dream, not a dated archival document in the strict sense.", "statut_attestation": "rapportee_par_tiers"}]$t$::jsonb,
  legendes_associees_en = $t$[{"titre": "The founding dream of the Bamum script", "statut": "legende", "description": "The origin of the writing project is presented, including by Njoya himself, as born of a prophetic dream: a master is said to have appeared to him in a dream to show him how to draw a hand on a wooden board, erase it, then drink the water used to wash it. A motif of spiritual legitimation common in African royal traditions, to be told as the story Njoya himself handed down, not as historical proof of the actual process."}]$t$::jsonb
